// OKF MCP server — generated by mcpify. Do not hand-edit.
//
// Interactive setup wizard (REQ-1.6): collects the API URL and the
// credentials the discovered auth scheme(s) need, then persists them per
// the operator's choice: a .env file, a local or global config.yml file,
// or a ready-to-run CLI invocation printed to stdout (nothing written to
// disk).
//
// Every secret (the Firecrawl PAT, and every LLM provider key, known or
// custom) always lives in the OS keychain/encrypted-file fallback via
// `save_credential` — that never changes. Separately, and only on
// explicit per-secret opt-in, a secret's real value may also be embedded
// in the `.env` file/printed MCP client config this wizard produces; by
// default nothing sensitive is written or printed anywhere but the
// keychain.
//
// Re-running this wizard reads whatever's already configured first:
// non-secret fields are pre-filled as editable defaults, and secret
// fields that already have a saved value offer a keep/overwrite choice
// instead of unconditionally re-prompting and re-saving.
//
// All actual `inquire` calls live behind the `Prompts` trait
// (`RealPrompts` is the only production impl) — every decision this
// wizard makes (what to ask, how to branch on the answer, what to save)
// is a plain function taking `&dyn Prompts`, so it's testable with a
// scripted fake instead of a real TTY. `inquire`'s prompts are blocking —
// `RealPrompts` runs them through `spawn_blocking`, the same pattern
// mcpify's own `auth_profile::prompt` documents for calling it from an
// async runtime.
//
// What each step actually asks/validates/persists lives in three
// submodules, grouped by stage: `prompts` (the ask-the-operator layer),
// `logic` (pure/non-interactive helpers the prompts build on), and
// `persistence` (writing this run's results to the keychain/.env/
// config.yml and printing the final MCP client config). This file is
// just the `Prompts` seam itself and the top-level orchestration that
// calls through all three in order.

mod logic;
mod persistence;
mod prompts;

use async_trait::async_trait;
use okf_mcp::core::config_schema::Transport;
use okf_mcp::core::credential_storage::save_credential;

use logic::{
    apply_reveals, build_runtime_settings, collect_revealable_secrets, existing_config_or_defaults,
    merge_custom_providers,
};
use persistence::{print_mcp_client_config, save_new_key};
use prompts::{
    prompt_api_version, prompt_auth_method, prompt_base_url, prompt_firecrawl_credentials,
    prompt_llm_providers, prompt_persistence, prompt_secret_reveal, prompt_transport,
};

/// Every interactive prompt shape this wizard uses, abstracted so
/// `RealPrompts` (production, backed by `inquire`) and a scripted test
/// fake can both implement it — every `prompt_*`/`run_setup_wizard_with`
/// function below is then plain, deterministic logic given a `&dyn
/// Prompts`, not itself coupled to a real terminal.
#[async_trait]
trait Prompts: Send + Sync {
    async fn text(&self, message: String, default: Option<String>) -> anyhow::Result<String>;
    async fn confirm(&self, message: String, default: bool) -> anyhow::Result<bool>;
    async fn password(&self, message: String) -> anyhow::Result<String>;
    async fn select(
        &self,
        message: String,
        choices: Vec<&'static str>,
        starting_cursor: usize,
    ) -> anyhow::Result<&'static str>;
    async fn multi_select(
        &self,
        message: String,
        choices: Vec<&'static str>,
        default_indices: Vec<usize>,
    ) -> anyhow::Result<Vec<&'static str>>;
}

struct RealPrompts;

#[async_trait]
impl Prompts for RealPrompts {
    async fn text(&self, message: String, default: Option<String>) -> anyhow::Result<String> {
        Ok(tokio::task::spawn_blocking(move || {
            let mut prompt = inquire::Text::new(&message);
            if let Some(default) = &default {
                prompt = prompt.with_default(default);
            }
            prompt.prompt()
        })
        .await??)
    }

    async fn confirm(&self, message: String, default: bool) -> anyhow::Result<bool> {
        Ok(tokio::task::spawn_blocking(move || {
            inquire::Confirm::new(&message)
                .with_default(default)
                .prompt()
        })
        .await??)
    }

    async fn password(&self, message: String) -> anyhow::Result<String> {
        Ok(tokio::task::spawn_blocking(move || {
            inquire::Password::new(&message)
                .without_confirmation()
                .prompt()
        })
        .await??)
    }

    async fn select(
        &self,
        message: String,
        choices: Vec<&'static str>,
        starting_cursor: usize,
    ) -> anyhow::Result<&'static str> {
        Ok(tokio::task::spawn_blocking(move || {
            inquire::Select::new(&message, choices)
                .with_starting_cursor(starting_cursor)
                .prompt()
        })
        .await??)
    }

    async fn multi_select(
        &self,
        message: String,
        choices: Vec<&'static str>,
        default_indices: Vec<usize>,
    ) -> anyhow::Result<Vec<&'static str>> {
        Ok(tokio::task::spawn_blocking(move || {
            inquire::MultiSelect::new(&message, choices)
                .with_default(&default_indices)
                .prompt()
        })
        .await??)
    }
}

async fn run_setup_wizard_with(prompts: &dyn Prompts) -> anyhow::Result<()> {
    let existing = existing_config_or_defaults();

    let url = prompt_base_url(prompts, &existing.firecrawl_base_url).await?;
    let auth_method = prompt_auth_method().await?;
    let (credentials, firecrawl_freshly_entered) =
        prompt_firecrawl_credentials(prompts, auth_method).await?;
    let api_version = prompt_api_version().await?;
    let transport = prompt_transport(prompts, existing.transport).await?;

    if firecrawl_freshly_entered {
        save_credential("firecrawl", &serde_json::to_string(&credentials)?)?;
        println!(
            "Saved Firecrawl credentials to your OS keychain (or the encrypted-file fallback)."
        );
    }

    let (known_providers, custom_providers) =
        prompt_llm_providers(prompts, &existing.custom_providers).await?;

    for provider in &known_providers {
        save_new_key(&provider.name, &provider.key)?;
    }
    for provider in &custom_providers {
        save_new_key(&provider.name, &provider.key)?;
    }

    let secrets = collect_revealable_secrets(&credentials, &known_providers, &custom_providers)?;

    let mut revealed = std::collections::HashSet::new();
    for secret in &secrets {
        if prompt_secret_reveal(prompts, &secret.label).await? {
            revealed.insert(secret.env_key.clone());
        }
    }

    let (mut env, mut config_fields) = build_runtime_settings(&url, &api_version, transport)?;
    merge_custom_providers(&mut env, &mut config_fields, &custom_providers);
    apply_reveals(&mut env, &secrets, &revealed);

    let secret_keys: std::collections::HashSet<String> =
        secrets.iter().map(|s| s.env_key.clone()).collect();
    prompt_persistence(prompts, &env, &config_fields, &secret_keys).await?;
    print_mcp_client_config(transport, auth_method, &env);

    let run_command = match transport {
        Transport::Stdio => "start",
        Transport::Http => "http",
    };
    println!("Setup complete! Run: okf-mcp {run_command}");
    Ok(())
}

pub async fn run_setup_wizard() -> anyhow::Result<()> {
    run_setup_wizard_with(&RealPrompts).await
}

